 private void updateTabs(){if(tabs==null)return;String[] names={"shop","custom","bag","account"},titles={"Shop","Custom","Bag",api.signedIn()?"Account":"Sign in"};int count=0;for(int i=0;i<cart.length();i++)count+=cart.optJSONObject(i).optInt("quantity");for(int i=0;i<4;i++){TextView t=(TextView)tabs.getChildAt(i);t.setText(titles[i]);t.setTextColor(page.equals(names[i])||(page.equals("detail")&&i==0)||(page.equals("checkout")&&i==2)?RED:MUTED);}badge.setText("Bag"+(count>0?" ("+count+")":""));}
