 private void shop(){label(body,"THE READY-MADE EDIT");body.addView(heading("A little bold.\nAll you.",40));space(body,12);body.addView(text("Beautifully considered outfits for the woman who dresses on her own terms.",15,MUTED));space(body,22);label(body,"6 OUTFITS · SWIPE TO EXPLORE");HorizontalScrollView swipe=new HorizontalScrollView(this);swipe.setHorizontalScrollBarEnabled(false);LinearLayout cards=horizontal();swipe.addView(cards);int width=Math.max(dp(245),getResources().getDisplayMetrics().widthPixels-dp(65));for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);LinearLayout card=vertical();card.setBackground(shape(Color.WHITE,14,true));card.setPadding(dp(10),dp(10),dp(10),dp(16));card.addView(picture(p.optString("id"),430));space(card,15);TextView name=heading(p.optString("name"),27);name.setTextColor(RED);card.addView(name);space(card,4);card.addView(text(p.optString("category"),12,MUTED));space(card,8);card.addView(text(money(p.optLong("price")),18,INK));card.addView(button("View outfit",false,()->{selected=p.optString("id");showPage("detail");}));LinearLayout.LayoutParams bounds=new LinearLayout.LayoutParams(width,-2);bounds.rightMargin=dp(16);cards.addView(card,bounds);}body.addView(swipe);space(body,25);LinearLayout bespoke=vertical();bespoke.setPadding(dp(20),dp(20),dp(20),dp(20));bespoke.setBackground(shape(Color.rgb(255,244,245),14,false));label(bespoke,"THE BESPOKE EXPERIENCE");bespoke.addView(heading("Your idea.\nOur craftsmanship.",29));space(bespoke,10);bespoke.addView(text("Create an outfit around your style, occasion and measurements.",14,MUTED));bespoke.addView(button("Create a custom outfit",true,()->showPage("custom")));body.addView(bespoke);space(body,18);body.addView(text("Sample collection and prices. Real orders open when the store is ready.",11,MUTED));}
 private void detail(){JSONObject p=product(selected);if(p==null){showPage("shop");return;}body.addView(button("‹ Back to collection",false,()->showPage("shop")));space(body,12);body.addView(picture(selected,440));space(body,18);label(body,p.optString("category"));TextView name=heading(p.optString("name"),34);name.setTextColor(RED);body.addView(name);space(body,12);body.addView(text(money(p.optLong("price")),23,RED));space(body,15);body.addView(text(p.optString("description"),15,MUTED));space(body,18);label(body,"Choose your size");JSONArray sizes=p.optJSONArray("sizes");String[] options=new String[sizes.length()];for(int i=0;i<options.length;i++)options[i]=sizes.optString(i);Spinner size=spinner(options,0);body.addView(size);space(body,10);body.addView(text("Fabric: "+p.optString("fabric"),13,MUTED));actionButton=button("Add to bag",true,()->changeCart(selected,options[size.getSelectedItemPosition()],"adjust",1));body.addView(actionButton);body.addView(button("View your bag",false,()->showPage("bag")));}
