 private void nativeSignIn(){work(()->api.prepareGoogle(),options->{busy=true;if(actionButton!=null)actionButton.setEnabled(false);try{googleCancel=NativeGoogle.signIn(this,options.getString("client"),options.getString("nonce"),command->handler.post(command),new NativeGoogle.Callback(){
  public void token(String token){ui(()->{busy=false;googleCancel=null;work(()->{api.finishGoogleToken(token);return json();},result->{cart=new JSONArray();cartVersion="";connection.setText("Restoring your account bag…");showPage("shop");importGuest();});});}
  public void error(String message){ui(()->{busy=false;googleCancel=null;api.cancelGoogle();if(actionButton!=null)actionButton.setEnabled(true);toast(message);});}
 });}catch(Exception failure){busy=false;api.cancelGoogle();if(actionButton!=null)actionButton.setEnabled(true);toast("Native Google sign-in is unavailable. Check Google Play services and the Android client setup.");}});}
 private void applyCart(JSONArray items,String version){if(!version.isEmpty()&&!cartVersion.isEmpty()&&version.compareTo(cartVersion)<0)return;if(!version.isEmpty())cartVersion=version;setAccountCart(items);}
 private void handleAuth(Intent intent){Uri data=intent==null?null:intent.getData();if(data==null)return;intent.setData(null);if("com.goodtreasure.fashion".equals(data.getScheme())&&"payment".equals(data.getHost())&&"/return".equals(data.getPath())){String reference=data.getQueryParameter("reference");if(reference!=null&&reference.equals(pendingPayment)&&api.signedIn())verifyPayment();}}
 private void importGuest(){JSONObject guest=vault.read("guest");JSONArray items=guest.optJSONArray("items");if(items==null||items.length()==0){refreshStore();startSync();return;}if(guest.optString("importId").isEmpty())put(guest,"importId",UUID.randomUUID().toString());vault.write("guest",guest);JSONObject request=json();put(request,"importId",guest.optString("importId"));put(request,"items",items);work(()->api.request("mobile/import-cart","POST",request),result->{vault.remove("guest");applyCart(result.getJSONArray("items"),result.optString("version"));refreshStore();startSync();toast("Your phone and account bags are now together.");});}
 private void work(Task task,Done done){if(busy)return;cartEpoch++;busy=true;if(actionButton!=null)actionButton.setEnabled(false);network.execute(()->{try{JSONObject result=task.run();ui(()->{busy=false;if(actionButton!=null)actionButton.setEnabled(true);try{done.accept(result);}catch(Exception failure){toast("Could not display the result. Please try again.");}});}catch(Exception failure){ui(()->{busy=false;if(actionButton!=null)actionButton.setEnabled(true);if(failure instanceof NativeApi.Failure&&((NativeApi.Failure)failure).status==401){stopSync();api.clearSession();cart=new JSONArray();cartVersion="";toast("Please sign in again.");showPage("account");}else toast(failure instanceof NativeApi.Failure?failure.getMessage():"Could not connect. Check your internet and try again.");});}});}
 private void refreshStore(){if(api==null||!api.signedIn()||busy||!active)return;final String identity=api.userId();final long epoch=cartEpoch;network.execute(()->{try{JSONObject result=api.request("store","GET",null);JSONObject user=result.optJSONObject("user");if(user==null||!identity.equals(user.optString("id")))throw new NativeApi.Failure(503,"Publish the native server update to connect your shared bag.");ui(()->{if(!api.signedIn()||busy||epoch!=cartEpoch||!identity.equals(api.userId()))return;store=result;connection.setText("Shared bag connected · "+api.email());JSONArray next=result.optJSONArray("cart");if(next!=null){String before=cart.toString();applyCart(next,result.optString("cartVersion"));if(!before.equals(cart.toString())&&page.equals("bag"))showPage("bag");}});}catch(Exception failure){ui(()->{if(!identity.equals(api.userId()))return;if(failure instanceof NativeApi.Failure&&((NativeApi.Failure)failure).status==401){api.clearSession();stopSync();cart=new JSONArray();showPage("account");}connection.setText(failure instanceof NativeApi.Failure?failure.getMessage():"Offline · Reconnect to restore your shared bag");});}});}
 private void startSync(){if(!active||!api.signedIn())return;stopSync();final int generation=syncGeneration;syncThread=new Thread(()->{while(active&&api.signedIn()&&generation==syncGeneration){try{HttpURLConnection c=api.stream();streamConnection=c;try(BufferedReader reader=new BufferedReader(new InputStreamReader(c.getInputStream(),"UTF-8"))){String event="",line;while(active&&generation==syncGeneration&&(line=reader.readLine())!=null){if(line.startsWith("event: "))event=line.substring(7);if(event.equals("cart")&&line.startsWith("data: ")){JSONObject value=new JSONObject(line.substring(6));ui(()->{if(generation!=syncGeneration||busy)return;connection.setText("Bag updates live across your devices");JSONArray next=value.optJSONArray("items");if(next!=null){String before=cart.toString();applyCart(next,value.optString("version"));if(!before.equals(cart.toString())&&page.equals("bag"))showPage("bag");}});}}}finally{c.disconnect();if(streamConnection==c)streamConnection=null;}}catch(Exception failure){ui(()->{if(generation==syncGeneration)connection.setText(failure instanceof NativeApi.Failure?failure.getMessage():"Reconnecting your saved bag…");});}try{Thread.sleep(1000);}catch(InterruptedException ignored){break;}}},"GoodTreasure-Bag");syncThread.setDaemon(true);syncThread.start();handler.postDelayed(new Runnable(){public void run(){if(generation!=syncGeneration||!active)return;refreshStore();handler.postDelayed(this,15000);}},15000);}
 private void stopSync(){syncGeneration++;HttpURLConnection c=streamConnection;if(c!=null)c.disconnect();if(syncThread!=null)syncThread.interrupt();}
 private Spinner spinner(String[] options,int selected){Spinner spinner=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,options);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(Math.max(0,Math.min(selected,options.length-1)));spinner.setBackground(shape(Color.WHITE,8,true));spinner.setPadding(dp(9),dp(5),dp(9),dp(5));spinner.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(50)));return spinner;}
