 private boolean requireContact(JSONObject data,boolean address){for(String key:new String[]{"name","email","phone","state","city"})if(data.optString(key).trim().isEmpty()){toast("Please complete your "+key+".");return false;}if(!android.util.Patterns.EMAIL_ADDRESS.matcher(data.optString("email")).matches()){toast("Enter a valid email address.");return false;}if(data.optString("city").equals("Other city / town")&&data.optString("otherCity").trim().length()<2){toast("Enter your city or town.");return false;}if(address&&data.optString("address").trim().length()<5){toast("Enter your delivery address.");return false;}return true;}
 private void submitCustom(JSONObject data){if(recording){toast("Stop recording first.");return;}if(!api.signedIn()){toast("Sign in before submitting. Your design is saved on your phone.");showPage("account");return;}if(data.optString("description").trim().length()<15){toast("Describe your outfit in at least 15 characters.");return;}if(!requireContact(data,false))return;if(data.optString("measurementMethod").equals("studio")&&data.optString("measurementDate").isEmpty()){toast("Choose a studio visit date.");return;}ArrayList<Attachment> images=new ArrayList<>(inspirations);Attachment audio=voice;JSONObject snapshot;try{snapshot=new JSONObject(data.toString());}catch(Exception ignored){return;}work(()->{JSONObject state=api.request("store","GET",null);if(!state.optBoolean("open"))throw new NativeApi.Failure(0,"Custom orders are not open yet. Your design is saved on this phone.");snapshot.put("images",upload(images));snapshot.put("audio",audio==null?JSONObject.NULL:upload(Collections.singletonList(audio)).getString(0));return api.request("custom","POST",snapshot);},result->{new AlertDialog.Builder(this).setTitle("Your idea is with us.").setMessage("Reference: "+result.optString("reference")+"\nWe’ll contact you to confirm the quote.").setPositiveButton("OK",(dialog,which)->showPage("shop")).show();});}
 private JSONArray upload(List<Attachment> files) throws Exception{if(files.isEmpty())return new JSONArray();JSONArray descriptors=new JSONArray();for(Attachment f:files)descriptors.put(new JSONObject().put("type",f.type).put("size",f.size));JSONObject signed=api.request("uploads/sign","POST",new JSONObject().put("files",descriptors));JSONArray urls=signed.getJSONArray("uploads"),paths=new JSONArray();for(int i=0;i<files.size();i++){Attachment f=files.get(i);JSONObject target=urls.getJSONObject(i);api.putFile(target.getString("url"),f.uri,f.type,f.size);paths.put(target.getString("path"));}return api.request("uploads/complete","POST",new JSONObject().put("paths",paths)).getJSONArray("paths");}
 private void checkout(){if(cart.length()==0){showPage("bag");return;}JSONObject data=draft("checkout");if(data.optString("email").isEmpty()&&api.signedIn())put(data,"email",api.email());if(data.optString("idempotencyKey").isEmpty())put(data,"idempotencyKey",UUID.randomUUID().toString());save("checkout",data);label(body,"THE FINAL DETAILS");body.addView(heading("Checkout",36));space(body,20);field(body,data,"checkout","name","Full name",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PERSON_NAME,false);field(body,data,"checkout","email","Email",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS,false);field(body,data,"checkout","phone","Phone number",InputType.TYPE_CLASS_PHONE,false);field(body,data,"checkout","address","Delivery address",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE,true);location(body,data,"checkout");summary("Subtotal",subtotal());long fee=store.optLong("deliveryFee",2500);summary("Delivery",fee);summary("Total",subtotal()+fee);label(body,"HOW WOULD YOU LIKE TO PAY?");Spinner method=spinner(new String[]{"Paystack — secure payment","Bank transfer"},data.optString("paymentMethod").equals("bank")?1:0);body.addView(method);method.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int at,long id){put(data,"paymentMethod",at==0?"paystack":"bank");save("checkout",data);}});space(body,12);body.addView(text("Card details are entered only on Paystack’s secure payment screen. Bank details appear after the order is created.",12,MUTED));CheckBox reminders=new CheckBox(this);reminders.setText("Email me a reminder if I leave items in my bag.");reminders.setTextSize(12);reminders.setOnCheckedChangeListener((control,checked)->{if(!api.signedIn()){control.setChecked(false);toast("Sign in to receive saved-bag reminders.");return;}work(()->api.request("cart/contact","POST",new JSONObject().put("consent",checked)),value->{});});body.addView(reminders);actionButton=button("Place order",true,()->{if(!api.signedIn()){toast("Sign in before checkout. Your bag is saved.");showPage("account");return;}if(!requireContact(data,true))return;placeOrder(data);});body.addView(actionButton);body.addView(text("Preview store: real orders remain closed until payments, stock and store details are ready.",12,MUTED));}
 private void placeOrder(JSONObject data){JSONObject request;try{request=new JSONObject(data.toString());}catch(Exception ignored){return;}work(()->{JSONObject state=api.request("store","GET",null);if(!state.optBoolean("open"))throw new NativeApi.Failure(0,"Checkout is not open yet. Your bag is saved.");return api.request("checkout","POST",request);},order->{setAccountCart(new JSONArray());put(data,"idempotencyKey",UUID.randomUUID().toString());save("checkout",data);String reference=order.optString("reference");if(order.optString("paymentMethod").equals("paystack")){pendingPayment=reference;vault.write("pending-payment",new JSONObject().put("reference",reference));startPayment(reference);}else{JSONObject bank=order.optJSONObject("bank");new AlertDialog.Builder(this).setTitle("Order received").setMessage("Reference: "+reference+"\n\n"+(bank==null?"":bank.optString("bank")+"\n"+bank.optString("accountName")+"\n"+bank.optString("accountNumber"))+"\n\nTransfer "+money(order.optLong("total"))+" and use your order reference. Payment remains unconfirmed until the store checks it.").setPositiveButton("OK",(dialog,which)->showPage("shop")).show();}});}
 private void startPayment(String reference){work(()->api.request("payments/start","POST",new JSONObject().put("reference",reference).put("returnTo","android")),result->{if(result.optBoolean("paid")){pendingPayment="";vault.remove("pending-payment");toast("Payment already verified.");showPage("shop");return;}Uri url=Uri.parse(result.optString("authorizationUrl"));if(!"https".equals(url.getScheme())||!"checkout.paystack.com".equals(url.getHost())){toast("Payment destination could not be verified.");return;}try{startActivity(new Intent(Intent.ACTION_VIEW,url));}catch(ActivityNotFoundException failure){toast("A browser is required for secure Paystack payment.");}});}
 private void verifyPayment(){if(busy||pendingPayment.isEmpty())return;String reference=pendingPayment;work(()->api.request("payments/verify","POST",new JSONObject().put("reference",reference)),result->{if(result.optBoolean("paid")){pendingPayment="";vault.remove("pending-payment");new AlertDialog.Builder(this).setTitle("Payment verified").setMessage("Reference: "+reference+(result.optBoolean("test")?"\nTest payment. No real funds collected.":"")).setPositiveButton("OK",(dialog,which)->showPage("shop")).show();}else new AlertDialog.Builder(this).setTitle("Payment awaiting confirmation").setMessage("Reference: "+reference).setPositiveButton("Check again",(dialog,which)->verifyPayment()).setNeutralButton("Pay now",(dialog,which)->startPayment(reference)).setNegativeButton("Later",null).show();});}
 private void pick(int request,String type){if(recording)stopRecording();Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT);picker.addCategory(Intent.CATEGORY_OPENABLE);picker.setType(type);picker.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(request==100){picker.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);picker.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp"});}try{startActivityForResult(picker,request);}catch(ActivityNotFoundException failure){toast("A file picker is not available on this phone.");}}
 private Attachment describe(Uri uri) throws Exception{String type=getContentResolver().getType(uri),name="Attachment";long size=-1;try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){int n=cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME),s=cursor.getColumnIndex(OpenableColumns.SIZE);if(n>=0)name=cursor.getString(n);if(s>=0&&!cursor.isNull(s))size=cursor.getLong(s);}}if(size<0)try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();size=0;byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1){size+=count;if(size>20*1048576L)break;}}if(type==null)type="";return new Attachment(uri,name,type,size);}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(result!=RESULT_OK||intent==null||(request!=100&&request!=101))return;ArrayList<Uri> selected=new ArrayList<>();if(intent.getClipData()!=null){for(int i=0;i<intent.getClipData().getItemCount();i++)selected.add(intent.getClipData().getItemAt(i).getUri());}else if(intent.getData()!=null)selected.add(intent.getData());try{ArrayList<Attachment> additions=new ArrayList<>();long bytes=0;for(Attachment f:inspirations)bytes+=f.size;for(Uri uri:selected){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}Attachment file=describe(uri);if(file.size<=0)throw new IOException("Empty file");if(request==100){boolean duplicate=false;for(Attachment old:inspirations)if(old.uri.equals(uri))duplicate=true;for(Attachment old:additions)if(old.uri.equals(uri))duplicate=true;if(duplicate)continue;if(!Arrays.asList("image/jpeg","image/png","image/webp").contains(file.type)){toast("Choose JPG, PNG or WebP images.");return;}bytes+=file.size;if(bytes>20*1048576L||inspirations.size()+additions.size()>=100){toast("Design images must total 20 MB or less, up to 100 images.");return;}additions.add(file);}else{if(!Arrays.asList("audio/webm","audio/mp4","audio/mpeg","audio/wav","audio/ogg").contains(file.type)||file.size>10*1048576L){toast("Choose a supported audio file up to 10 MB.");return;}voice=file;}}if(request==100)inspirations.addAll(additions);saveFiles();showPage("custom");}catch(Exception failure){toast("Could not read that file. Choose another.");}}
 private JSONObject attachment(Attachment f){JSONObject value=json();put(value,"uri",f.uri.toString());put(value,"name",f.name);put(value,"type",f.type);put(value,"size",f.size);return value;}
 private Attachment attachment(JSONObject value){return new Attachment(Uri.parse(value.optString("uri")),value.optString("name"),value.optString("type"),value.optLong("size"));}
 private void saveFiles(){JSONObject value=json();JSONArray images=new JSONArray();for(Attachment f:inspirations)images.put(attachment(f));put(value,"images",images);if(voice!=null)put(value,"audio",attachment(voice));vault.write("attachments",value);}
 private void restoreFiles(){JSONObject files=vault.read("attachments");JSONArray images=files.optJSONArray("images");if(images!=null)for(int i=0;i<images.length();i++)inspirations.add(attachment(images.optJSONObject(i)));JSONObject audio=files.optJSONObject("audio");if(audio!=null)voice=attachment(audio);}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==102&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)startRecording();else if(request==102)toast("You can upload an audio file instead.");}
 private void startRecording(){try{stopPlayer();recordedFile=File.createTempFile("GT-voice-",".m4a",getCacheDir());recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioEncodingBitRate(96000);recorder.setAudioSamplingRate(44100);recorder.setMaxDuration(120000);recorder.setMaxFileSize(10*1048576L);recorder.setOutputFile(recordedFile.getAbsolutePath());recorder.setOnInfoListener((r,what,extra)->{if(what==MediaRecorder.MEDIA_RECORDER_INFO_MAX_DURATION_REACHED||what==MediaRecorder.MEDIA_RECORDER_INFO_MAX_FILESIZE_REACHED)stopRecording();});recorder.prepare();recorder.start();recording=true;if(recordButton!=null)recordButton.setText("Stop recording");toast("Recording. Tap Stop when you’re finished.");}catch(Exception failure){if(recorder!=null)recorder.release();recorder=null;recording=false;toast("Microphone unavailable. Upload an audio file instead.");}}
 private void stopRecording(){if(!recording||recorder==null)return;recording=false;try{recorder.stop();if(recordedFile.length()>0)voice=new Attachment(Uri.fromFile(recordedFile),"Recorded voice note","audio/mp4",recordedFile.length());saveFiles();}catch(Exception failure){toast("The recording was too short. Try again.");}finally{recorder.release();recorder=null;if(recordButton!=null)recordButton.setText("Record a voice note");}if(active&&page.equals("custom"))showPage("custom");}
 private void playVoice(){if(voice==null)return;stopPlayer();try{player=MediaPlayer.create(this,voice.uri);if(player==null)throw new IOException();player.setOnCompletionListener(value->stopPlayer());player.start();}catch(Exception failure){toast("That voice note is unavailable. Upload it again.");}}
 private void stopPlayer(){if(player!=null){player.release();player=null;}}
